-- Marca da Click Consultoria (logo + cores) no link e no PDF da proposta revisional.
-- Depende de 20261112_revisional_marca.sql (coluna marca).
insert into public.revisional_config (workspace_id, empresa_nome, marca)
values ('clickconsultoria', 'Click Consultoria',
  jsonb_build_object('cor', '#1E5235', 'cor2', '#C9A24D', 'logo', 'data:image/jpeg;base64,'))
on conflict (workspace_id) do update set
  marca = excluded.marca,
  empresa_nome = case when coalesce(revisional_config.empresa_nome, '') = '' then excluded.empresa_nome else revisional_config.empresa_nome end,
  updated_at = now();